def f(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: continue
            near1=any(0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==1 for dr,dc in((-1,0),(1,0),(0,-1),(0,1)))
            n2diag=any(0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==2 for dr,dc in((-1,-1),(-1,1),(1,-1),(1,1)))
            out[r][c]=7 if near1 else (4 if n2diag else bg)
    return out
